body:
I'm experiencing the following change of behavior when bumping xunit to from 2.4.2 to 2.5.0.

Given:

```csharp
public class BitArrayComparer : IEqualityComparer<BitArray>
{
    public bool Equals(BitArray? x, BitArray? y)
    {
        return x?.ToBitString() == y?.ToBitString();
    }

    public int GetHashCode(BitArray obj)
    {
        return obj.ToBitString().GetHashCode();
    }
}
```

and the following test code:

```csharp
public class BitArrayComparerTest
{
    [Fact]
    public void BitArrayComparer()
    {
        var set = new HashSet<BitArray>
            {
                new BitArray(new[] { true, false }),
                new BitArray(new[] { false, true }),
            };

        var otherSet = new HashSet<BitArray>
            {
                new BitArray(new[] { true, false }),
                new BitArray(new[] { false, true }),
            };

        // Without the comparer
        Assert.NotEqual(set, otherSet);
        Assert.False(set == otherSet);

        var aggregatedSet = new HashSet<BitArray>();
        set.ForEach(s => aggregatedSet.Add(s));
        otherSet.ForEach(s => aggregatedSet.Add(s));
        Assert.Equal(4, aggregatedSet.Count);

        // Using the comparer
        Assert.Equal(set, otherSet, new BitArrayComparer());      // <----- Passing before, failing now
}
```

This test went red when Dependabot tried to bump xunit version in this PR: https://github.com/eduherminio/SheepTools/pull/136

```log
[xUnit.net 00:00:03.38]     SheepTools.Test.BitArrayComparerTest.BitArrayComparer [FAIL]
